files.content:
:host {
  display: block;
  width: 100%;
  height: 100%;
}

:host,
.empty-state,
.empty-state__text {
  box-sizing: border-box;
}

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  width: 100%;
  text-align: center;
}

.empty-state__icon {
  margin-block-end: var(--dimension-space-100);
  flex: 0 0 auto;
}

.empty-state__text {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--dimension-space-050);
  width: 100%;
}

.empty-state__actions {
  margin-block-start: var(--dimension-space-200);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: var(--dimension-space-100);
}

.empty-state__actions:not(:has([slot='actions'])) {
  display: none;
}

.empty-state__title,
.empty-state__body {
  text-wrap: balance;
}

import { Component, Prop, h, Host } from '@stencil/core';

/**
 * @slot actions - Optional recovery buttons or links. The consumer owns their labels and behavior.
 */
@Component({
  tag: 'ds-empty-state',
  styleUrl: 'EmptyState.css',
  scoped: true,
})
export class EmptyState {
  /** Optional decorative prefix glyph for the complete icon + title + body variant. */
  @Prop() icon: string | undefined;
  /** Optional visual title. Use with body; required when icon is provided. */
  @Prop() heading: string | undefined;
  /** Explanatory empty-state copy. Every supported variant includes body text. */
  @Prop() body: string = '';

  render() {
    const showHeading = Boolean(this.heading?.trim());
    const showIcon = showHeading && Boolean(this.icon);

    return (
      <Host>
        <div class="empty-state">
          {showIcon && (
            <ds-icon class="empty-state__icon" name={this.icon} size="xl" color="primary" />
          )}
          <div class="empty-state__text">
            {showHeading && (
              <ds-text
                class="empty-state__title"
                as="div"
                variant="text-title-small"
                color="primary"
                align="center"
              >
                {this.heading}
              </ds-text>
            )}
            {this.body && (
              <ds-text
                class="empty-state__body"
                as="p"
                variant="text-body-medium"
                color="secondary"
                align="center"
              >
                {this.body}
              </ds-text>
            )}
          </div>
          <div class="empty-state__actions">
            <slot name="actions" />
          </div>
        </div>
      </Host>
    );
  }
}
